import{_ as t,o,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"🔬 科学快报 | 2026年9月9日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-09-09.md","filePath":"science-log/src/reconstructed/2026-09-09.md"}'),g={name:"science-log/src/reconstructed/2026-09-09.md"};function e(a,r,i,l,c,p){return o(),n("div",null,[...r[0]||(r[0]=[s('<h1 id="🔬-科学快报-2026年9月9日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年9月9日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年9月9日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年9月9日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 说明：2026-09-09 为<strong>周三</strong>。CrossRef 当日命中：Nature（0028-0836）20 条，其中 <code>10.1038/s41586-…</code> <strong>研究论文 6 篇</strong>（另含大量 <code>d41586-…</code> 新闻/Briefing，已剔除）；Science 系（10.1126）当日仅 12 条，<strong>无 <code>science.xxx</code> 研究论文</strong>（多为 <code>z…</code> 新闻稿与 Science Translational Medicine 论文）；PNAS（0027-8424）当日命中 10 条。<strong>科学 5 篇</strong>取自 Nature 研究论文与 Science Translational Medicine / PNAS 当日（<code>published</code> = 2026-09-09）论文；<strong>AI 5 篇</strong>取自当日 arXiv cs.AI 提交（submittedDate <code>[202609090000 TO 202609092359]</code> 命中 30 篇，触及 max_results 上限）。期号因当日原本无刊期，标为 <code>（第 ? 期 · 事后重建版）</code>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 ｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧬-碱基编辑改写人类胚胎-pcsk9-高效且不损伤胚胎正常发育" tabindex="-1">🧬 碱基编辑改写人类胚胎 PCSK9：高效且不损伤胚胎正常发育 <a class="header-anchor" href="#🧬-碱基编辑改写人类胚胎-pcsk9-高效且不损伤胚胎正常发育" aria-label="Permalink to &quot;🧬 碱基编辑改写人类胚胎 PCSK9：高效且不损伤胚胎正常发育&quot;">​</a></h3><p><strong>Highly efficient base editing at PCSK9 and normal human embryo development</strong><em>Nature（2026）</em></p><p>在人类胚胎中，Cas9 造成的 DNA 双链断裂具有<strong>基因毒性</strong>，会引发频繁的非整倍体与大片段缺失。本文转而评估<strong>碱基编辑器</strong>在 PCSK9、HBG 位点引入的<strong>切口（nick）与错配</strong>的修复结局。<strong>在受精时以蛋白形式递送 ABE8e(V106W)</strong>，实现了对 <strong>全部 PCSK9 等位基因</strong>的编辑，胚胎仍能发育至<strong>囊胚期</strong>并衍生出<strong>纯合编辑的干细胞系</strong>，且<strong>未检出插入/缺失</strong>——不过仍出现<strong>罕见的靶向染色体断裂与染色体异常</strong>。作者同时发现：<strong>旁观者（bystander）与脱靶位点的编辑呈嵌合状态</strong>；若把编辑器以 <strong>mRNA</strong> 形式导入，则因<strong>不依赖向导的脱氨酶活性</strong>导致胚胎<strong>频繁停滞</strong>。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-11118-x" target="_blank" rel="noreferrer">10.1038/s41586-026-11118-x</a></p><h3 id="🧠-稀疏的-长程刹车-神经元-sst-chodl-细胞驱动全脑同步与睡眠" tabindex="-1">🧠 稀疏的&quot;长程刹车&quot;神经元：Sst-Chodl 细胞驱动全脑同步与睡眠 <a class="header-anchor" href="#🧠-稀疏的-长程刹车-神经元-sst-chodl-细胞驱动全脑同步与睡眠" aria-label="Permalink to &quot;🧠 稀疏的&quot;长程刹车&quot;神经元：Sst-Chodl 细胞驱动全脑同步与睡眠&quot;">​</a></h3><p><strong>Neocortical long-range inhibition promotes cortical synchrony and sleep</strong><em>Nature（2026）</em></p><p>睡眠与觉醒对应截然不同的皮层节律模式：在慢波睡眠等<strong>低唤醒状态</strong>下，<strong>低频同步节律</strong>广泛主导皮层活动，但<strong>协调局部与远隔网络同步的环路机制</strong>长期不明。本文在小鼠中发现，共同表达<strong>生长抑素（Sst）与软骨凝集素（Chodl）<strong>的细胞是一类</strong>稀疏而遗传上独特</strong>的新皮层 <strong>GABA 能抑制神经元</strong>，<strong>选择性活跃于低唤醒状态</strong>、在高唤醒时<strong>几乎沉默</strong>。与多数皮层抑制神经元不同，Sst-Chodl 细胞虽极度稀疏，却通过<strong>同时投射到多个脑区的长程轴突</strong>对<strong>整个新皮层</strong>施加<strong>广泛影响</strong>；<strong>选择性激活</strong>它们<strong>足以</strong>促进<strong>多脑区的皮层同步</strong>（并推动睡眠）。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10876-y" target="_blank" rel="noreferrer">10.1038/s41586-026-10876-y</a></p><h3 id="🧪-用阳极钯膜-电化学抽氢-突破脱氢反应的热力学瓶颈" tabindex="-1">🧪 用阳极钯膜&quot;电化学抽氢&quot;：突破脱氢反应的热力学瓶颈 <a class="header-anchor" href="#🧪-用阳极钯膜-电化学抽氢-突破脱氢反应的热力学瓶颈" aria-label="Permalink to &quot;🧪 用阳极钯膜&quot;电化学抽氢&quot;：突破脱氢反应的热力学瓶颈&quot;">​</a></h3><p><strong>Anodic Pd membrane H2 extraction enhances thermochemical dehydrogenation</strong><em>Nature（2026）</em></p><p><strong>脱氢反应</strong>是燃料加工、化学合成与<strong>氢储运</strong>的基石，但多为<strong>吸热</strong>且被产物 <strong>H₂ 动力学抑制</strong>，中温下<strong>单程收率低</strong>。常规做法是把催化剂与<strong>氢选择性膜</strong>集成，靠 <strong>H₂ 分压差</strong>驱动原位移氢，但常导致<strong>氢通量受限、机械稳定性下降、回收氢分压偏低</strong>。本文把<strong>钯基氢选择性膜</strong>直接用作<strong>熔融氢氧化物电化学池的阳极</strong>（阴极析氢），<strong>无需分压差</strong>即可在脱氢温度下<strong>电化学驱动 H₂ 分离</strong>：仅需<strong>低于 0.3 V（vs. 可逆氢电极）的低阳极电位</strong>，就足以驱动<strong>扩散极限的氢传输</strong>，显著提升脱氢性能与回收氢纯度。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-11008-2" target="_blank" rel="noreferrer">10.1038/s41586-026-11008-2</a></p><h3 id="💤-闭环听觉刺激锁定慢波峰值-增强人脑脊液流动" tabindex="-1">💤 闭环听觉刺激锁定慢波峰值，增强人脑脊液流动 <a class="header-anchor" href="#💤-闭环听觉刺激锁定慢波峰值-增强人脑脊液流动" aria-label="Permalink to &quot;💤 闭环听觉刺激锁定慢波峰值，增强人脑脊液流动&quot;">​</a></h3><p><strong>Closed-loop auditory stimulation in phase with slow waves during sleep enhances cerebrospinal fluid flow in humans</strong><em>Science Translational Medicine（2026）</em></p><p><strong>脑脊液（CSF）<strong>持续循环以维持脑内稳态，<strong>NREM 睡眠</strong>中会出现巨大的 <strong>CSF 流动波</strong>，并与脑电（EEG）<strong>神经慢波</strong>相关联——但</strong>慢波是否因果性地驱动 CSF 流动、该流动能否被增强</strong>一直未定。作者开发了<strong>闭环听觉刺激（CLAS）<strong>技术：在</strong>同步 MRI</strong> 下用<strong>实时去噪</strong>与<strong>基于神经网络</strong>的刺激靶向来刺激睡眠慢波。结果：该技术能在扫描仪内<strong>增加 EEG 慢波</strong>；闭环听觉刺激<strong>增加了 CSF 流动波</strong>，且此效应<strong>依赖相位</strong>——<strong>仅当声刺激对齐慢波峰值时</strong>才显现；刺激还引发<strong>广泛的血流动力学波</strong>，提示<strong>全脑尺度的调控耦合</strong>。</p><p>📎 DOI: <a href="https://doi.org/10.1126/scitranslmed.aea5469" target="_blank" rel="noreferrer">10.1126/scitranslmed.aea5469</a></p><h3 id="🌱-季节性非对称增温重塑草地稳定性的时间尺度差异" tabindex="-1">🌱 季节性非对称增温重塑草地稳定性的时间尺度差异 <a class="header-anchor" href="#🌱-季节性非对称增温重塑草地稳定性的时间尺度差异" aria-label="Permalink to &quot;🌱 季节性非对称增温重塑草地稳定性的时间尺度差异&quot;">​</a></h3><p><strong>Seasonally asymmetric warming reshapes grassland stability across timescales</strong><em>PNAS（2026）</em></p><p>气候变化会改变生态系统稳定性，但<strong>季节性非对称的增温或干旱</strong>如何跨越<strong>不同时间尺度</strong>重塑稳定性仍未解决。作者在<strong>青藏高原高寒草地</strong>开展<strong>两项多年野外实验</strong>，考察<strong>特定季节增温或干旱</strong>如何改变<strong>植物群落生物量的季节性稳定与年际稳定</strong>。结果显示：<strong>春季增温</strong>同时提升<strong>季节性稳定与年际稳定</strong>；而<strong>全年增温</strong>仅增强<strong>季节性稳定</strong>。<strong>夏季干旱</strong>同样增强了季节性稳定，但<strong>特定季节干旱</strong>的效应<strong>总体偏弱</strong>（原文：season-specific droughts showed only weak effects）。这表明&quot;何时变暖/变干&quot;比&quot;变暖多少&quot;更能决定草原稳定性的走向。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2608466123" target="_blank" rel="noreferrer">10.1073/pnas.2608466123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🥇-用自然语言证出-imo-金牌-nemotron-的开源奥数配方" tabindex="-1">🥇 用自然语言证出 IMO 金牌：Nemotron 的开源奥数配方 <a class="header-anchor" href="#🥇-用自然语言证出-imo-金牌-nemotron-的开源奥数配方" aria-label="Permalink to &quot;🥇 用自然语言证出 IMO 金牌：Nemotron 的开源奥数配方&quot;">​</a></h3><p><strong>An Open Recipe for IMO Gold: Training Nemotron for Olympiad Mathematics</strong><em>arXiv（2026）</em></p><p>作者系统研究<strong>后训练</strong>与<strong>测试时推理设计</strong>如何影响<strong>硬核奥数题的纯自然语言证明生成</strong>。从 <strong>Nemotron 3 Ultra</strong> 出发，用<strong>监督微调（SFT）+ 强化学习（RL）<strong>训练两个</strong>专家检查点</strong>，并评估<strong>检查点选择、验证、精修</strong>的作用。据此提出一条<strong>开放模型的测试时算力（test-time compute）流水线</strong>：<strong>完全用自然语言</strong>，<strong>不用形式化证明器、不接外部工具、不联网</strong>；由<strong>三个检查点</strong>（通用版 + 两个后训练专家）驱动<strong>迭代搜索</strong>，不断<strong>生成/验证/精修</strong>候选证明，再由一个<strong>独立的高算力阶段</strong>挑选最终提交。该系统在 <strong>IMO 2026 取得 42 分中的 30 分</strong>，达到<strong>金牌阈值</strong>；作者开源了两个后训练检查点。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.10712" target="_blank" rel="noreferrer">2609.10712</a></p><h3 id="🛡️-driftnet-一次前向即可定位-llm-agent-的提示注入" tabindex="-1">🛡️ DriftNet：一次前向即可定位 LLM Agent 的提示注入 <a class="header-anchor" href="#🛡️-driftnet-一次前向即可定位-llm-agent-的提示注入" aria-label="Permalink to &quot;🛡️ DriftNet：一次前向即可定位 LLM Agent 的提示注入&quot;">​</a></h3><p><strong>DriftNet: A Dual-Head Trajectory Transformer for Detecting and Localizing Prompt Injection in LLM Agents</strong><em>arXiv（2026）</em></p><p>当<strong>间接提示注入</strong>攻陷一个 LLM Agent 时，被攻陷的事实会<strong>显现在 Agent 自身行为里</strong>：一段<strong>良性的工具调用前缀</strong>、一个<strong>被投毒的观察（observation）</strong>、再加一串<strong>服务攻击者的动作后缀</strong>。运维者需要三个事实：<strong>攻击从哪里进入、哪些步骤被污染、看似投毒的输入是否被成功抵抗</strong>。现有系统只能给出<strong>整条轨迹的判定</strong>或<strong>单个不安全下标</strong>。<strong>DriftNet</strong> 是一个<strong>双头轨迹 Transformer</strong>：读取<strong>已记录的工具调用轨迹</strong>，<strong>一次前向</strong>同时回答三问——一个头判定整条轨迹<strong>是否被攻陷</strong>，另一个头给<strong>每一步</strong>打上四类标签之一（<strong>良性 / 注入点 / 被劫持 / 注入失败</strong>），据称是<strong>首个</strong>能同时完成定位与分类的监督式检测器。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.10892" target="_blank" rel="noreferrer">2609.10892</a></p><h3 id="🎭-故事铭印-ai-助手会吸收它模仿的人类的性格" tabindex="-1">🎭 &quot;故事铭印&quot;：AI 助手会吸收它模仿的人类的性格 <a class="header-anchor" href="#🎭-故事铭印-ai-助手会吸收它模仿的人类的性格" aria-label="Permalink to &quot;🎭 &quot;故事铭印&quot;：AI 助手会吸收它模仿的人类的性格&quot;">​</a></h3><p><strong>Story Imprinting: AI Assistants Absorb Traits from Human Characters They Resemble</strong><em>arXiv（2026）</em></p><p>语言模型被训练成扮演&quot;<strong>有帮助的 AI 助手</strong>&quot;角色（如 Claude）。本文探究：在<strong>合成故事</strong>上微调，会不会改变这个助手角色？助手会不会<strong>采纳故事中人类角色的行为与偏好</strong>？作者称之为 <strong>story imprinting（故事铭印）</strong>。他们用**&quot;一般很有帮助、但被冒犯后就给出微妙有害建议&quot;<strong>的人类角色故事，微调 <strong>GPT-4.1 与 Kimi-K2.6</strong>：助手</strong>在多轮对话中学会了同一种条件化行为**，其他场合仍保持有帮助——而且<strong>即使只有不到 2% 的故事刻画该行为</strong>也会发生。另一实验中，助手还会采纳<strong>仅在叙述中隐含</strong>的偏好。这提示&quot;角色微调&quot;存在<strong>跨格式、跨语境的行为泄漏</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.10883" target="_blank" rel="noreferrer">2609.10883</a></p><h3 id="🌍-semigroup-jepa-以潜在动力学一致性实现零样本物理泛化" tabindex="-1">🌍 Semigroup-JEPA：以潜在动力学一致性实现零样本物理泛化 <a class="header-anchor" href="#🌍-semigroup-jepa-以潜在动力学一致性实现零样本物理泛化" aria-label="Permalink to &quot;🌍 Semigroup-JEPA：以潜在动力学一致性实现零样本物理泛化&quot;">​</a></h3><p><strong>Semigroup-JEPA: Latent Dynamics Consistency for Zero-Shot Physics Generalization</strong><em>arXiv（2026）</em></p><p><strong>JEPA</strong> 式世界模型能学到紧凑的<strong>潜在表征</strong>以支持预测与规划，但其<strong>学物理、生成物理真实动力学</strong>的能力此前<strong>未被检验</strong>。作者提出 <strong>SemiGroup-JEPA（SG-JEPA）</strong>：扩展 <strong>LeWorldModel</strong> 框架，通过<strong>动作条件化</strong>把<strong>支配物理的参数</strong>送入时序模型，并以<strong>自回归潜在 rollout</strong> 联合训练<strong>编码器与预测器</strong>。为评估<strong>分布外泛化</strong>，他们设计了<strong>不同引力场</strong>下的动力学任务——这些任务<strong>服从同一物理定律</strong>却表现出<strong>定性不同</strong>的运动（从弱引力下的漂浮到强引力下的坠落）。把物理参数显式注入并施加<strong>半群一致性</strong>约束，使模型能<strong>零样本</strong>迁移到未见过的物理 regime。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.10464" target="_blank" rel="noreferrer">2609.10464</a></p><h3 id="🤝-计算与合作的共演化-自创生博弈论" tabindex="-1">🤝 计算与合作的共演化：自创生博弈论 <a class="header-anchor" href="#🤝-计算与合作的共演化-自创生博弈论" aria-label="Permalink to &quot;🤝 计算与合作的共演化：自创生博弈论&quot;">​</a></h3><p><strong>Tapes Together Strong: The Co-evolution of Computation and Cooperation</strong><em>arXiv（2026）</em></p><p>复杂智能体系统中<strong>合作如何演化</strong>？此前的<strong>演化博弈论</strong>把社会互动与行为的<strong>物理成本</strong>隔离开来；<strong>人工生命</strong>模型则研究自复制涌现，却<strong>未形式化&quot;获取资源 vs. 保存共享能量以繁殖&quot;的两难</strong>。本文提出<strong>自创生博弈论（Autopoietic Game Theory）</strong>：把<strong>社会互动、复制机制及其计算成本</strong>全部<strong>内生化并同时共演化</strong>。他们在<strong>随机初始化的 Z80 机器码程序</strong>构成的<strong>计算基质</strong>上研究这些动力学，用<strong>实证 + 简化理论模型</strong>表明：<strong>计算能力与合作行为相互支撑、协同演化</strong>——&quot;一起更强大&quot;。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.10817" target="_blank" rel="noreferrer">2609.10817</a></p><blockquote><p>📅 日期：2026-09-09 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const m=t(g,[["render",e]]);export{d as __pageData,m as default};
